-- Shared eTok visibility; friendship means reciprocal follows, never profile identity access.
CREATE OR REPLACE FUNCTION public.etok_are_friends(p_owner uuid,p_viewer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.etok_follows WHERE follower_id=p_owner AND following_id=p_viewer) AND EXISTS(SELECT 1 FROM public.etok_follows WHERE follower_id=p_viewer AND following_id=p_owner); $$;
CREATE OR REPLACE FUNCTION public.etok_not_blocked(p_owner uuid,p_viewer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.etok_blocked_users WHERE (blocker_id=p_owner AND blocked_id=p_viewer) OR (blocker_id=p_viewer AND blocked_id=p_owner)); $$;
CREATE OR REPLACE FUNCTION public.can_view_etok_video(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.etok_videos v WHERE v.id=p_id AND (v.author_id=auth.uid() OR (public.etok_not_blocked(v.author_id,auth.uid()) AND (v.privacy='everyone' OR (v.privacy='friends' AND public.etok_are_friends(v.author_id,auth.uid()))) AND (NOT EXISTS(SELECT 1 FROM public.etok_privacy_settings ps WHERE ps.user_id=v.author_id AND ps.private_account) OR EXISTS(SELECT 1 FROM public.etok_follows f WHERE f.following_id=v.author_id AND f.follower_id=auth.uid()))))); $$;
REVOKE ALL ON FUNCTION public.etok_are_friends(uuid,uuid),public.etok_not_blocked(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.etok_are_friends(uuid,uuid),public.etok_not_blocked(uuid,uuid) TO service_role;
REVOKE ALL ON FUNCTION public.can_view_etok_video(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_view_etok_video(uuid) TO anon,authenticated,service_role;
DROP POLICY IF EXISTS etok_videos_select ON public.etok_videos;
CREATE POLICY etok_videos_select ON public.etok_videos FOR SELECT USING(public.can_view_etok_video(id));
DROP POLICY IF EXISTS etok_videos_update ON public.etok_videos;
CREATE POLICY etok_videos_update ON public.etok_videos FOR UPDATE TO authenticated USING(author_id=auth.uid()) WITH CHECK(author_id=auth.uid());
CREATE POLICY etok_videos_delete_owner ON public.etok_videos FOR DELETE TO authenticated USING(author_id=auth.uid());
REVOKE UPDATE ON public.etok_videos FROM authenticated;
GRANT UPDATE(description,hashtags,sound_name,thumbnail_url,privacy,allow_comments,allow_duet,allow_stitch,allow_download) ON public.etok_videos TO authenticated;
GRANT SELECT,INSERT,DELETE ON public.etok_videos TO authenticated;
GRANT ALL ON public.etok_videos TO service_role;
CREATE OR REPLACE FUNCTION public.guard_etok_video_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN NEW.views:=0;NEW.likes:=0;NEW.comments:=0;NEW.shares:=0;NEW.is_sponsored:=false; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_etok_video_insert BEFORE INSERT ON public.etok_videos FOR EACH ROW EXECUTE FUNCTION public.guard_etok_video_insert();

CREATE OR REPLACE FUNCTION public.can_comment_etok(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.can_view_etok_video(p_id) AND EXISTS(SELECT 1 FROM public.etok_videos v WHERE v.id=p_id AND v.allow_comments AND (NOT EXISTS(SELECT 1 FROM public.etok_privacy_settings p WHERE p.user_id=v.author_id AND (p.allow_comments='no_one' OR (p.allow_comments='friends' AND NOT public.etok_are_friends(v.author_id,auth.uid()) AND v.author_id<>auth.uid()))))); $$;
REVOKE ALL ON FUNCTION public.can_comment_etok(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_comment_etok(uuid) TO authenticated,service_role;
DROP POLICY IF EXISTS etok_comments_select ON public.etok_comments;
DROP POLICY IF EXISTS etok_comments_insert ON public.etok_comments;
DROP POLICY IF EXISTS etok_comments_delete ON public.etok_comments;
CREATE POLICY etok_comments_select ON public.etok_comments FOR SELECT TO authenticated USING(public.can_view_etok_video(video_id));
CREATE POLICY etok_comments_insert ON public.etok_comments FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND public.can_comment_etok(video_id));
CREATE POLICY etok_comments_delete ON public.etok_comments FOR DELETE TO authenticated USING(author_id=auth.uid() OR EXISTS(SELECT 1 FROM public.etok_videos v WHERE v.id=video_id AND v.author_id=auth.uid()));
DROP POLICY IF EXISTS etok_likes_select ON public.etok_likes;
DROP POLICY IF EXISTS etok_likes_insert ON public.etok_likes;
CREATE POLICY etok_likes_select ON public.etok_likes FOR SELECT TO authenticated USING(public.can_view_etok_video(video_id));
CREATE POLICY etok_likes_insert ON public.etok_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.can_view_etok_video(video_id));
GRANT SELECT,INSERT,DELETE ON public.etok_comments,public.etok_likes,public.etok_follows TO authenticated;
GRANT ALL ON public.etok_comments,public.etok_likes,public.etok_follows TO service_role;
CREATE OR REPLACE FUNCTION public.validate_etok_comment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF char_length(btrim(NEW.text))=0 OR char_length(NEW.text)>2000 THEN RAISE EXCEPTION 'Comment must contain 1–2000 characters'; END IF; IF NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.etok_comments WHERE id=NEW.parent_id AND video_id=NEW.video_id) THEN RAISE EXCEPTION 'Reply must belong to the same video'; END IF; IF current_setting('request.jwt.claim.role',true)='authenticated' OR auth.uid() IS NOT NULL THEN NEW.likes:=0;NEW.is_pinned:=false; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_etok_comment BEFORE INSERT ON public.etok_comments FOR EACH ROW EXECUTE FUNCTION public.validate_etok_comment();
CREATE OR REPLACE FUNCTION public.sync_etok_content_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid;v_delta integer;v_author uuid; BEGIN IF TG_OP='INSERT' THEN v_id:=NEW.video_id;v_delta:=1; ELSE v_id:=OLD.video_id;v_delta:=-1; END IF; IF TG_TABLE_NAME='etok_likes' THEN UPDATE public.etok_videos SET likes=greatest(0,likes+v_delta) WHERE id=v_id RETURNING author_id INTO v_author; ELSE UPDATE public.etok_videos SET comments=greatest(0,comments+v_delta) WHERE id=v_id RETURNING author_id INTO v_author; END IF; IF TG_OP='INSERT' AND v_author IS NOT NULL THEN INSERT INTO public.etok_video_analytics_daily(video_id,author_id,date,likes,comments) VALUES(v_id,v_author,current_date,CASE WHEN TG_TABLE_NAME='etok_likes' THEN 1 ELSE 0 END,CASE WHEN TG_TABLE_NAME='etok_comments' THEN 1 ELSE 0 END) ON CONFLICT(video_id,date) DO UPDATE SET likes=etok_video_analytics_daily.likes+excluded.likes,comments=etok_video_analytics_daily.comments+excluded.comments; END IF; RETURN NULL; END $$;
CREATE TRIGGER sync_etok_likes AFTER INSERT OR DELETE ON public.etok_likes FOR EACH ROW EXECUTE FUNCTION public.sync_etok_content_count();
CREATE TRIGGER sync_etok_comments AFTER INSERT OR DELETE ON public.etok_comments FOR EACH ROW EXECUTE FUNCTION public.sync_etok_content_count();
CREATE OR REPLACE FUNCTION public.set_etok_like(p_video uuid,p_liked boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_uid uuid:=auth.uid();v_count integer; BEGIN IF v_uid IS NULL OR NOT public.can_view_etok_video(p_video) THEN RAISE EXCEPTION 'Video unavailable'; END IF; PERFORM 1 FROM public.etok_videos WHERE id=p_video FOR UPDATE; IF p_liked THEN INSERT INTO public.etok_likes(user_id,video_id) VALUES(v_uid,p_video) ON CONFLICT(user_id,video_id) DO NOTHING; ELSE DELETE FROM public.etok_likes WHERE user_id=v_uid AND video_id=p_video; END IF; SELECT likes INTO v_count FROM public.etok_videos WHERE id=p_video; RETURN jsonb_build_object('liked',p_liked,'likes',v_count); END $$;
REVOKE ALL ON FUNCTION public.set_etok_like(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_etok_like(uuid,boolean) TO authenticated,service_role;
CREATE TABLE public.etok_saved_videos(user_id uuid NOT NULL,video_id uuid NOT NULL REFERENCES public.etok_videos(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,video_id));
GRANT SELECT,INSERT,DELETE ON public.etok_saved_videos TO authenticated;
GRANT ALL ON public.etok_saved_videos TO service_role;
ALTER TABLE public.etok_saved_videos ENABLE ROW LEVEL SECURITY;
CREATE POLICY saved_videos_read ON public.etok_saved_videos FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY saved_videos_insert ON public.etok_saved_videos FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.can_view_etok_video(video_id));
CREATE POLICY saved_videos_delete ON public.etok_saved_videos FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.etok_video_view_receipts(video_id uuid NOT NULL REFERENCES public.etok_videos(id) ON DELETE CASCADE,user_id uuid NOT NULL,day date NOT NULL DEFAULT current_date,PRIMARY KEY(video_id,user_id,day));
GRANT SELECT ON public.etok_video_view_receipts TO authenticated;
GRANT ALL ON public.etok_video_view_receipts TO service_role;
ALTER TABLE public.etok_video_view_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY video_view_receipts_read ON public.etok_video_view_receipts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.record_etok_video_view(_video_id uuid,_source text DEFAULT 'fyp') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_author uuid;v_n integer;BEGIN IF auth.uid() IS NULL OR NOT public.can_view_etok_video(_video_id) THEN RETURN; END IF; INSERT INTO public.etok_video_view_receipts(video_id,user_id) VALUES(_video_id,auth.uid()) ON CONFLICT DO NOTHING; GET DIAGNOSTICS v_n=ROW_COUNT; IF v_n=0 THEN RETURN; END IF; UPDATE public.etok_videos SET views=views+1 WHERE id=_video_id RETURNING author_id INTO v_author; INSERT INTO public.etok_video_analytics_daily(video_id,author_id,date,views,source_fyp,source_following,source_search,source_profile) VALUES(_video_id,v_author,current_date,1,CASE WHEN _source='fyp' THEN 1 ELSE 0 END,CASE WHEN _source='following' THEN 1 ELSE 0 END,CASE WHEN _source='search' THEN 1 ELSE 0 END,CASE WHEN _source='profile' THEN 1 ELSE 0 END) ON CONFLICT(video_id,date) DO UPDATE SET views=etok_video_analytics_daily.views+1,source_fyp=etok_video_analytics_daily.source_fyp+excluded.source_fyp,source_following=etok_video_analytics_daily.source_following+excluded.source_following,source_search=etok_video_analytics_daily.source_search+excluded.source_search,source_profile=etok_video_analytics_daily.source_profile+excluded.source_profile;END $$;
CREATE OR REPLACE FUNCTION public.record_etok_video_interaction(_video_id uuid,_kind text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_author uuid;BEGIN IF auth.uid() IS NULL OR _kind<>'share' OR NOT public.can_view_etok_video(_video_id) THEN RETURN; END IF; UPDATE public.etok_videos SET shares=shares+1 WHERE id=_video_id RETURNING author_id INTO v_author; INSERT INTO public.etok_video_analytics_daily(video_id,author_id,date,shares) VALUES(_video_id,v_author,current_date,1) ON CONFLICT(video_id,date) DO UPDATE SET shares=etok_video_analytics_daily.shares+1; END $$;
REVOKE ALL ON FUNCTION public.record_etok_video_view(uuid,text),public.record_etok_video_interaction(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.record_etok_video_view(uuid,text),public.record_etok_video_interaction(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.search_etok_videos(p_query text) RETURNS SETOF public.etok_videos LANGUAGE sql STABLE SET search_path=public AS $$ SELECT v.* FROM public.etok_videos v WHERE length(btrim(p_query))>0 AND (position(lower(ltrim(btrim(p_query),'#')) in lower(v.description))>0 OR position(lower(ltrim(btrim(p_query),'#')) in lower(v.sound_name))>0 OR EXISTS(SELECT 1 FROM unnest(v.hashtags) h WHERE position(lower(ltrim(btrim(p_query),'#')) in lower(h))>0)) ORDER BY v.views DESC,v.created_at DESC,v.id DESC LIMIT 30; $$;
REVOKE ALL ON FUNCTION public.search_etok_videos(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.search_etok_videos(text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.can_read_etok_media(p_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (split_part(p_name,'/',1)=auth.uid()::text) OR EXISTS(SELECT 1 FROM public.etok_videos v WHERE public.can_view_etok_video(v.id) AND (v.video_url='etok-videos/'||p_name OR split_part(v.video_url,'?',1) LIKE '%/etok-videos/'||p_name)); $$;
REVOKE ALL ON FUNCTION public.can_read_etok_media(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_read_etok_media(text) TO authenticated,service_role;
DROP POLICY IF EXISTS "Etok videos are publicly accessible" ON storage.objects;
CREATE POLICY etok_media_authorized_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='etok-videos' AND public.can_read_etok_media(name));

-- Stories: owner-controlled audiences and live-object authorization.
CREATE TABLE public.story_close_friends(owner_id uuid NOT NULL,contact_user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,contact_user_id));
GRANT SELECT,INSERT,DELETE ON public.story_close_friends TO authenticated;
GRANT ALL ON public.story_close_friends TO service_role;
ALTER TABLE public.story_close_friends ENABLE ROW LEVEL SECURITY;
CREATE POLICY story_close_friends_read ON public.story_close_friends FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY story_close_friends_insert ON public.story_close_friends FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND contact_user_id<>auth.uid());
CREATE POLICY story_close_friends_delete ON public.story_close_friends FOR DELETE TO authenticated USING(owner_id=auth.uid());
ALTER TABLE public.user_stories ADD COLUMN privacy text NOT NULL DEFAULT 'everyone',ADD COLUMN media_path text;
CREATE OR REPLACE FUNCTION public.story_content_privacy(p_content text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE p text; BEGIN BEGIN p:=p_content::jsonb->>'privacy'; EXCEPTION WHEN OTHERS THEN p:=NULL;END; RETURN CASE WHEN p IN ('contacts','close_friends','everyone') THEN p ELSE 'everyone' END;END $$;
UPDATE public.user_stories SET privacy=public.story_content_privacy(content),media_path=CASE WHEN media_url LIKE 'chat-media/%' THEN substr(media_url,12) WHEN media_url LIKE '%/object/%/chat-media/%' THEN split_part(regexp_replace(media_url,'^.*?/chat-media/',''), '?',1) ELSE NULL END;
CREATE OR REPLACE FUNCTION public.can_view_story(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_stories s WHERE s.id=p_id AND (s.user_id=auth.uid() OR (auth.uid() IS NOT NULL AND s.expires_at>now() AND (s.privacy='everyone' OR (s.privacy='contacts' AND EXISTS(SELECT 1 FROM public.profile_contacts WHERE owner_id=s.user_id AND contact_user_id=auth.uid())) OR (s.privacy='close_friends' AND EXISTS(SELECT 1 FROM public.story_close_friends WHERE owner_id=s.user_id AND contact_user_id=auth.uid())))))); $$;
REVOKE ALL ON FUNCTION public.can_view_story(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_view_story(uuid) TO authenticated,service_role;
DROP POLICY IF EXISTS stories_select ON public.user_stories;
CREATE POLICY stories_select ON public.user_stories FOR SELECT TO authenticated USING(public.can_view_story(id));
GRANT SELECT,INSERT,DELETE ON public.user_stories TO authenticated;
GRANT ALL ON public.user_stories TO service_role;
CREATE OR REPLACE FUNCTION public.validate_story_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.privacy NOT IN ('everyone','contacts','close_friends') THEN RAISE EXCEPTION 'Invalid story audience'; END IF; IF NEW.media_path IS NOT NULL AND NEW.media_path NOT LIKE 'stories/'||NEW.user_id::text||'/%' THEN RAISE EXCEPTION 'Story media owner mismatch'; END IF; IF current_user='authenticated' THEN NEW.views_count:=0;NEW.created_at:=now();NEW.expires_at:=now()+interval '24 hours'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_story_insert BEFORE INSERT ON public.user_stories FOR EACH ROW EXECUTE FUNCTION public.validate_story_insert();
DROP POLICY IF EXISTS sv_insert ON public.story_views;
CREATE POLICY sv_insert ON public.story_views FOR INSERT TO authenticated WITH CHECK(viewer_id=auth.uid() AND public.can_view_story(story_id) AND NOT EXISTS(SELECT 1 FROM public.user_stories s WHERE s.id=story_id AND s.user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.sync_story_view_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.user_stories SET views_count=coalesce(views_count,0)+1 WHERE id=NEW.story_id; RETURN NULL; END $$;
CREATE TRIGGER sync_story_view_count AFTER INSERT ON public.story_views FOR EACH ROW EXECUTE FUNCTION public.sync_story_view_count();
CREATE OR REPLACE FUNCTION public.can_read_story_media(p_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (split_part(p_name,'/',1)='stories' AND split_part(p_name,'/',2)=auth.uid()::text) OR EXISTS(SELECT 1 FROM public.user_stories s WHERE s.media_path=p_name AND public.can_view_story(s.id)); $$;
REVOKE ALL ON FUNCTION public.can_read_story_media(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_read_story_media(text) TO authenticated,service_role;
CREATE POLICY story_media_authorized_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='chat-media' AND public.can_read_story_media(name));
CREATE POLICY story_media_owner_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='chat-media' AND split_part(name,'/',1)='stories' AND split_part(name,'/',2)=auth.uid()::text);
CREATE POLICY story_media_owner_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='chat-media' AND split_part(name,'/',1)='stories' AND split_part(name,'/',2)=auth.uid()::text);

-- Channels: no self-invitation into private channels; immutable post attribution.
DROP POLICY IF EXISTS "subscribe self" ON public.channel_subscribers;
CREATE POLICY "subscribe self" ON public.channel_subscribers FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.channels c WHERE c.id=channel_id AND (c.is_public OR c.created_by=auth.uid())));
REVOKE UPDATE ON public.channel_posts FROM authenticated;
GRANT UPDATE(content,type,edited) ON public.channel_posts TO authenticated;
REVOKE UPDATE ON public.channels FROM authenticated;
GRANT UPDATE(name,description,is_public,avatar_color,pinned_message_id,link) ON public.channels TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_channel_insert_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user='authenticated' THEN IF TG_TABLE_NAME='channels' THEN NEW.subscriber_count:=0; ELSE NEW.views:=0;NEW.reactions:='{}'::jsonb;NEW.sender_name:=''; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_channel_insert_fields BEFORE INSERT ON public.channels FOR EACH ROW EXECUTE FUNCTION public.guard_channel_insert_fields();
CREATE TRIGGER guard_channel_post_insert_fields BEFORE INSERT ON public.channel_posts FOR EACH ROW EXECUTE FUNCTION public.guard_channel_insert_fields();
CREATE OR REPLACE FUNCTION public.sync_channel_subscriber_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN UPDATE public.channels SET subscriber_count=subscriber_count+1 WHERE id=NEW.channel_id; ELSE UPDATE public.channels SET subscriber_count=greatest(0,subscriber_count-1) WHERE id=OLD.channel_id; END IF;RETURN NULL;END $$;
CREATE OR REPLACE FUNCTION public.get_channel_posts_page(p_channel_id text,p_before timestamptz DEFAULT NULL,p_before_id text DEFAULT NULL) RETURNS TABLE(id text,channel_id text,sender_id uuid,sender_name text,content text,type text,views integer,edited boolean,reactions jsonb,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT cp.id,cp.channel_id,cp.sender_id,CASE WHEN public.can_read_profile(cp.sender_id) THEN coalesce(p.name,p.username,'Hidden profile') ELSE 'Hidden profile' END,cp.content,cp.type,cp.views,cp.edited,cp.reactions,cp.created_at FROM public.channel_posts cp LEFT JOIN public.profiles p ON p.id=cp.sender_id WHERE auth.uid() IS NOT NULL AND cp.channel_id=p_channel_id AND public.can_view_channel(cp.channel_id,auth.uid()) AND (p_before IS NULL OR (cp.created_at,cp.id)<(p_before,coalesce(p_before_id,''))) ORDER BY cp.created_at DESC,cp.id DESC LIMIT 100; $$;
REVOKE ALL ON FUNCTION public.get_channel_posts_page(text,timestamptz,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_channel_posts_page(text,timestamptz,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_channel_posts_safe(p_channel_id text) RETURNS TABLE(id text,channel_id text,sender_id uuid,sender_name text,content text,type text,views integer,edited boolean,reactions jsonb,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT * FROM public.get_channel_posts_page(p_channel_id,NULL,NULL) ORDER BY created_at,id; $$;

-- Live streams: nonrecursive owner updates, actual memberships and host-directed signaling.
ALTER TABLE public.etok_live_streams ADD COLUMN last_heartbeat timestamptz NOT NULL DEFAULT now();
DROP POLICY IF EXISTS live_streams_update ON public.etok_live_streams;
CREATE POLICY live_streams_update ON public.etok_live_streams FOR UPDATE TO authenticated USING(host_id=auth.uid()) WITH CHECK(host_id=auth.uid());
REVOKE UPDATE ON public.etok_live_streams FROM authenticated;
GRANT UPDATE(title,category,is_live,ended_at,last_heartbeat) ON public.etok_live_streams TO authenticated;
CREATE OR REPLACE FUNCTION public.etok_live_active(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.etok_live_streams s WHERE s.id=p_id AND s.is_live AND s.last_heartbeat>now()-interval '2 minutes'); $$;
CREATE OR REPLACE FUNCTION public.etok_valid_signal(p_stream uuid,p_from uuid,p_to uuid,p_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_from=auth.uid() AND p_from<>p_to AND EXISTS(SELECT 1 FROM public.etok_live_streams s WHERE s.id=p_stream AND public.etok_live_active(s.id) AND ((p_from=s.host_id AND p_kind IN ('offer','ice') AND EXISTS(SELECT 1 FROM public.etok_live_viewers v WHERE v.stream_id=s.id AND v.user_id=p_to)) OR (p_to=s.host_id AND p_kind IN ('request','answer','ice') AND EXISTS(SELECT 1 FROM public.etok_live_viewers v WHERE v.stream_id=s.id AND v.user_id=p_from)))); $$;
REVOKE ALL ON FUNCTION public.etok_live_active(uuid),public.etok_valid_signal(uuid,uuid,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.etok_live_active(uuid),public.etok_valid_signal(uuid,uuid,uuid,text) TO authenticated,service_role;
DROP POLICY IF EXISTS rtc_insert ON public.etok_webrtc_signals;
CREATE POLICY rtc_insert ON public.etok_webrtc_signals FOR INSERT TO authenticated WITH CHECK(public.etok_valid_signal(stream_id,from_user_id,to_user_id,signal_type));
DROP POLICY IF EXISTS live_viewers_insert ON public.etok_live_viewers;
CREATE POLICY live_viewers_insert ON public.etok_live_viewers FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.etok_live_active(stream_id));
DROP POLICY IF EXISTS live_comments_insert ON public.etok_live_comments;
CREATE POLICY live_comments_insert ON public.etok_live_comments FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND public.etok_live_active(stream_id));
CREATE OR REPLACE FUNCTION public.sync_live_viewer_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN UPDATE public.etok_live_streams SET viewer_count=viewer_count+1 WHERE id=NEW.stream_id; ELSE UPDATE public.etok_live_streams SET viewer_count=greatest(0,viewer_count-1) WHERE id=OLD.stream_id;END IF;RETURN NULL;END $$;
CREATE TRIGGER sync_live_viewer_count AFTER INSERT OR DELETE ON public.etok_live_viewers FOR EACH ROW EXECUTE FUNCTION public.sync_live_viewer_count();
CREATE OR REPLACE FUNCTION public.heartbeat_etok_live(p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.etok_live_streams SET last_heartbeat=now() WHERE id=p_id AND host_id=auth.uid() AND is_live; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.heartbeat_etok_live(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.heartbeat_etok_live(uuid) TO authenticated,service_role;
GRANT SELECT,INSERT,DELETE ON public.etok_live_viewers,public.etok_webrtc_signals TO authenticated;
GRANT SELECT,INSERT ON public.etok_live_comments,public.etok_live_streams TO authenticated;
GRANT ALL ON public.etok_live_streams,public.etok_live_comments,public.etok_live_viewers,public.etok_webrtc_signals TO service_role;